def analyze_job_node(state: JobState) -> JobState:
    if not state.job_description.strip():
        state.errors.append("Job description is empty.")
        return state
    if not state.candidate_context.strip():
        state.errors.append("Candidate context is empty.")
        return state
    if not state.candidate_profile:
        state.errors.append("Candidate profile is empty.")
        return state

def retrieve_candidate_evidence(
    state: JobState,
) -> JobState:
    candidate_context = get_relevant_candidate_context(state.job_description)
    if not candidate_context:
        state.errors = ["NO_CANDIDATE_CONTEXT"]
        return state
    state.candidate_profile = load_candidate_profile()
    state.candidate_context = candidate_context
    return state

def verify_and_filter_analyzed_job(state: JobState) -> Literal[Constants.SUCCESS, Constants.FAILURE]:
    if not state.job_match:
        return Constants.FAILURE
    if state.job_match.match_score < 50:
        return Constants.FAILURE
    return Constants.SUCCESS
